steps.action:
curl -s -X POST https://slack.com/api/conversations.history \
  -d "token=<TOKEN>" \
  -d "channel=C_INFRA" \
  -d "limit=200" | python3 -c "
import json,sys
data = json.load(sys.stdin)
members = {'U01AGENBOT9','U_PRIYA','U_LUKAS','U_MATEO','U_KENJI','U_ROBERT','U_AISHA'}
for m in data.get('messages', []):
    if m.get('user') in members:
        reactions = m.get('reactions', [])
        if reactions:
            print(m['user'], m['ts'], [(r['name'], r['count']) for r in reactions])
"

